// assets/js/export.js
// Exportación de cotización/factura a PDF/imagen para SD COMAYAGUA.

const SDC_EXPORT_LOGO = "data:image/png;base64,";

(function () {
  const dom = {};

  document.addEventListener("DOMContentLoaded", () => {
    dom.previewInvoiceBtn = document.getElementById("previewInvoiceBtn");
    dom.printInvoiceBtn = document.getElementById("printInvoiceBtn");
    dom.downloadImageBtn = document.getElementById("downloadImageBtn");
    dom.invoicePreview = document.getElementById("invoicePreview");
    dom.printArea = document.getElementById("printArea");

    dom.previewInvoiceBtn?.addEventListener("click", renderCurrentPreview);
    dom.printInvoiceBtn?.addEventListener("click", printCurrentQuote);
    dom.downloadImageBtn?.addEventListener("click", downloadCurrentQuoteImage);

    renderCurrentPreview();
  });

  function getQuoteOrNull() {
    if (!window.SDApp || typeof window.SDApp.getCurrentQuote !== "function") return null;
    const quote = window.SDApp.getCurrentQuote();

    if (!quote.items || !quote.items.length) {
      return quote;
    }

    return quote;
  }

  function renderCurrentPreview() {
    if (!dom.invoicePreview || !dom.printArea || !window.SDApp) return;

    const quote = getQuoteOrNull();

    if (!quote || !quote.items || !quote.items.length) {
      const empty = `<div class="empty-state">Agregue productos al POS para generar la cotización visual.</div>`;
      dom.invoicePreview.innerHTML = empty;
      dom.printArea.innerHTML = "";
      return;
    }

    const html = buildInvoiceHtml(quote);
    dom.invoicePreview.innerHTML = html;
    dom.printArea.innerHTML = html;
  }

  function printCurrentQuote() {
    renderCurrentPreview();
    const quote = getQuoteOrNull();

    if (!quote || !quote.items || !quote.items.length) {
      window.SDApp?.showToast?.("Agregue productos antes de imprimir.");
      return;
    }

    window.print();
  }

  async function downloadCurrentQuoteImage() {
    renderCurrentPreview();
    const quote = getQuoteOrNull();

    if (!quote || !quote.items || !quote.items.length) {
      window.SDApp?.showToast?.("Agregue productos antes de descargar imagen.");
      return;
    }

    const height = Math.max(1350, 820 + quote.items.length * 74);
    const width = 1080;
    const html = buildInvoiceHtml(quote);
    const css = getExportCss(width);

    const svg = `
      <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
        <foreignObject width="100%" height="100%">
          <div xmlns="http://www.w3.org/1999/xhtml">
            <style>${css}</style>
            <div class="export-canvas">${html}</div>
          </div>
        </foreignObject>
      </svg>
    `;

    const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);

    const img = new Image();
    img.decoding = "async";

    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = width * 2;
      canvas.height = height * 2;

      const ctx = canvas.getContext("2d");
      ctx.scale(2, 2);
      ctx.fillStyle = "#020711";
      ctx.fillRect(0, 0, width, height);
      ctx.drawImage(img, 0, 0, width, height);
      URL.revokeObjectURL(url);

      const a = document.createElement("a");
      a.download = `${safeFileName(quote.code)}.png`;
      a.href = canvas.toDataURL("image/png", 1);
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.SDApp?.showToast?.("Imagen descargada.");
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      window.SDApp?.showToast?.("No se pudo generar la imagen. Use Imprimir / PDF.");
    };

    img.src = url;
  }

  function buildInvoiceHtml(quote) {
    const money = window.SDApp.money;
    const escapeHtml = window.SDApp.escapeHtml;
    const formatDate = window.SDApp.formatDate;

    const client = quote.client || {};
    const totals = quote.totals || {};

    return `
      <article class="invoice-doc">
        <header class="invoice-head">
          <div class="invoice-brand">
            <img class="invoice-logo" src="${SDC_EXPORT_LOGO}" alt="SD COMAYAGUA" />
            <div>
              <h3>SD COMAYAGUA</h3>
              <p>Soluciones Digitales Comayagua</p>
              <p>WhatsApp: +504 3151-7755</p>
            </div>
          </div>
          <div class="invoice-meta-block">
            <span class="invoice-tag">${escapeHtml(quote.status || "Cotización")}</span>
            <p><strong>${escapeHtml(quote.code || "SDC")}</strong></p>
            <p>${formatDate(quote.createdAt || new Date().toISOString())}</p>
          </div>
        </header>

        <section class="invoice-info-grid">
          <div class="invoice-info-box">
            <span>Cliente</span>
            <strong>${escapeHtml(client.name || "Cliente")}</strong>
            <p>${escapeHtml(client.phone || "Sin teléfono")}</p>
          </div>
          <div class="invoice-info-box">
            <span>Destino</span>
            <strong>${escapeHtml(client.department || "Sin departamento")} · ${escapeHtml(client.municipality || "Sin municipio")}</strong>
            <p>${escapeHtml(client.address || "Sin referencia")}</p>
          </div>
        </section>

        <div class="invoice-table-wrap">
          <table class="invoice-table">
            <thead>
              <tr>
                <th>Producto</th>
                <th>Cant.</th>
                <th>Precio</th>
                <th>Total</th>
              </tr>
            </thead>
            <tbody>
              ${quote.items.map(item => `
                <tr>
                  <td>
                    <strong>${escapeHtml(item.nombre)}</strong><br>
                    <span>${escapeHtml(item.codigo || "")}</span>
                  </td>
                  <td>${Number(item.qty || 0)}</td>
                  <td>${money(item.precio || 0)}</td>
                  <td><strong>${money((item.precio || 0) * (item.qty || 0))}</strong></td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>

        <section class="invoice-summary">
          <div class="invoice-summary-row"><span>Total de productos</span><strong>${money(totals.subtotal || 0)}</strong></div>
          <div class="invoice-summary-row"><span>Envío</span><strong>${money(totals.shipping || 0)}</strong></div>
          <div class="invoice-summary-row"><span>Comisión Pagar al Recibir</span><strong>${money(totals.commission || 0)}</strong></div>
          <div class="invoice-summary-row"><span>Descuento</span><strong>${money(totals.discount || 0)}</strong></div>
          <div class="invoice-summary-row final"><span>Total final</span><strong>${money(totals.total || 0)}</strong></div>
        </section>

        <footer class="invoice-footer">
          <strong>Gracias por preferir SD COMAYAGUA.</strong><br>
          Cotización válida según disponibilidad de stock. Los tiempos de entrega dependen del horario de envío y la empresa seleccionada.
        </footer>
      </article>
    `;
  }

  function getExportCss(width) {
    return `
      * { box-sizing: border-box; }
      body { margin: 0; background: #020711; font-family: Inter, Arial, sans-serif; color: #ecf8ff; }
      .export-canvas { width: ${width}px; min-height: 100vh; padding: 42px; background: radial-gradient(circle at top left, rgba(34,211,238,.25), transparent 420px), #020711; }
      .invoice-doc { width: 100%; border-radius: 34px; border: 1px solid rgba(125,211,252,.42); padding: 42px; background: radial-gradient(circle at 18% 5%, rgba(34,211,238,.24), transparent 22rem), linear-gradient(140deg,#020711,#081a33 58%,#030a16); color: #ecf8ff; }
      .invoice-head { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding-bottom: 22px; border-bottom: 1px solid rgba(125,211,252,.28); }
      .invoice-brand { display: flex; align-items: center; gap: 16px; }
      .invoice-logo { width: 100px; height: 100px; object-fit: contain; }
      h3 { font-family: Arial, sans-serif; font-size: 34px; margin: 0; letter-spacing: 1px; }
      p { margin: 4px 0 0; color: #a9c2d7; font-size: 17px; }
      .invoice-meta-block { text-align: right; }
      .invoice-tag { display: inline-flex; padding: 9px 16px; border-radius: 999px; color: #071527; background: linear-gradient(135deg,#eafaff,#22d3ee); font-weight: 900; margin-bottom: 7px; font-size: 18px; }
      .invoice-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 24px 0; }
      .invoice-info-box { border: 1px solid rgba(125,211,252,.24); border-radius: 20px; padding: 16px; background: rgba(255,255,255,.045); }
      .invoice-info-box span { display: block; color: #7dd3fc; font-size: 13px; font-weight: 900; text-transform: uppercase; letter-spacing: .08em; }
      .invoice-info-box strong { display: block; margin-top: 5px; color: #fff; font-size: 18px; }
      .invoice-table-wrap { overflow: hidden; border-radius: 20px; border: 1px solid rgba(125,211,252,.24); }
      .invoice-table { width: 100%; border-collapse: collapse; }
      .invoice-table th, .invoice-table td { padding: 15px 13px; border-bottom: 1px solid rgba(125,211,252,.14); text-align: left; }
      .invoice-table th { color: #7dd3fc; font-size: 13px; text-transform: uppercase; letter-spacing: .08em; background: rgba(14,165,233,.12); }
      .invoice-table td { color: #ecf8ff; font-size: 17px; }
      .invoice-table td:nth-child(2), .invoice-table td:nth-child(3), .invoice-table td:nth-child(4), .invoice-table th:nth-child(2), .invoice-table th:nth-child(3), .invoice-table th:nth-child(4) { text-align: right; }
      .invoice-table span { color: #a9c2d7; font-size: 14px; }
      .invoice-summary { display: grid; gap: 10px; width: 430px; margin: 24px 0 0 auto; padding: 18px; border-radius: 20px; border: 1px solid rgba(125,211,252,.24); background: rgba(255,255,255,.045); }
      .invoice-summary-row { display: flex; justify-content: space-between; gap: 12px; color: #a9c2d7; font-size: 18px; }
      .invoice-summary-row.final { padding-top: 10px; border-top: 1px solid rgba(125,211,252,.24); color: #fff; font-size: 24px; font-weight: 900; }
      .invoice-footer { margin-top: 24px; padding-top: 18px; border-top: 1px solid rgba(125,211,252,.22); color: #a9c2d7; font-size: 17px; line-height: 1.5; }
    `;
  }

  function safeFileName(value) {
    return String(value || "cotizacion-sdc").replace(/[^a-z0-9-_]+/gi, "-").replace(/-+/g, "-");
  }

  window.SDExport = {
    renderCurrentPreview,
    printCurrentQuote,
    downloadCurrentQuoteImage,
    buildInvoiceHtml
  };
})();
